content.content:
pub fn claim(
    items: &[Item],
    paid_so_far: i64,
    damages: &[Damage],
) -> Result<Settlement, String> {
    let cap_available = payout_cap_of(items)? - paid_so_far;
    let payout = desired_payout_of(items, damages).min(cap_available);
    Ok(Settlement {
        payout,
        remaining_cap: cap_available - payout,
    })
}
fn desired_payout_of(items: &[Item], damages: &[Damage]) -> i64 {
    damages
        .iter()
        .map(|damage| reimbursement_of(insured_item_damaged_by(items, damage), damage))
        .sum()
}
fn insured_item_damaged_by<'a>(items: &'a [Item], damage: &Damage) -> Option<&'a Item> {
    items
        .iter()
        .find(|item| item.item_type == damage.item_type)
}
fn reimbursement_of(damaged_item: Option<&Item>, damage: &Damage) -> i64 {
    reimbursable_damage_of(damaged_item, damage) - DEDUCTIBLE
}

